// Take the address out of whatever the caller sent.
//
// A form posts JSON, a CRM posts form-encoded fields, and somebody will call it
// with ?email= from a browser to see whether it works. All three are normal and
// all three land here.
//
// single-item input: one request, one address.
// Read from the trigger by name: Settings sits between it and here, and a Set
// node replaces the item, so $input at this point would be the config.
const req = $('When A Form Calls').first().json || {};
const body = (req.body && typeof req.body === 'object') ? req.body : {};
const query = req.query || {};

const raw = String(
  body.email || body.Email || body.EMAIL ||
  (body.data && body.data.email) || body.address ||
  query.email || ''
).trim().toLowerCase();

// Deliberately not the RFC 5322 grammar, which allows quoted strings, comments
// and addresses no form on earth accepts. This is what a mail server will take.
const shaped = /^[^\s@"'<>(),;:\\]+@[^\s@.]+(\.[^\s@.]+)+$/.test(raw) && raw.length <= 254;
const at = raw.lastIndexOf('@');
const local = at > 0 ? raw.slice(0, at) : '';
const domain = at > 0 ? raw.slice(at + 1) : '';

// Gmail ignores dots and everything after a plus. Two addresses that differ
// only there are one mailbox, and counting them separately is how the same
// person looks like six leads.
let canonical = raw;
if (domain === 'gmail.com' || domain === 'googlemail.com') {
  canonical = local.split('+')[0].replace(/\./g, '') + '@gmail.com';
} else {
  canonical = local.split('+')[0] + '@' + domain;
}

return [{ json: {
  email: raw,
  local: local,
  domain: domain,
  address_key: canonical,
  looks_like_an_address: shaped,
  // The DNS nodes below run on every request, so an unusable domain still has
  // to be a resolvable string rather than an empty one.
  lookup_domain: shaped ? domain : 'invalid.invalid',
}}];

// Four answers, read carefully, because the difference between them is the
// whole product.
//
// Read by name rather than from the input: the Merge above is a barrier that
// proves all four have arrived, and its output is four unrelated payloads in
// one stream.
const asked = $('Read The Address').first().json;

function payload(nodeName) {
  const j = $(nodeName).first().json || {};
  if (j.Status !== undefined) { return j; }
  if (typeof j.body === 'object' && j.body) { return j.body; }
  if (typeof j.data === 'string') {
    try { return JSON.parse(j.data); } catch (e) { return {}; }
  }
  return j;
}

const mx = payload('Look Up The MX Records');
const a = payload('Look Up The A Record');
const dmarc = payload('Look Up DMARC');

// Status 3 is NXDOMAIN. A domain that does not exist and a domain with no MX
// both come back with no Answer array, and only Status tells them apart.
const nxdomain = Number(mx.Status) === 3 || Number(a.Status) === 3;

const mxAnswers = (mx.Answer || []).filter(function (r) { return Number(r.type) === 15; });
const hosts = mxAnswers.map(function (r) {
  return String(r.data || '').replace(/^\d+\s+/, '').replace(/\.$/, '').toLowerCase();
}).filter(Boolean);

// RFC 7505: one MX record, priority 0, target "." means the domain accepts no
// mail at all. It is a single valid MX answer, so anything that counts records
// calls this deliverable. example.com publishes exactly this.
const nullMx = mxAnswers.length === 1 && /^\s*0\s+\.\s*$/.test(String(mxAnswers[0].data || ''));

const aAnswers = (a.Answer || []).filter(function (r) { return Number(r.type) === 1; });

const dmarcTxt = (dmarc.Answer || [])
  .map(function (r) { return String(r.data || '').replace(/"/g, ''); })
  .filter(function (t) { return /^v=DMARC1/i.test(t); });

const spf = payload('Look Up SPF');
const spfTxt = (spf.Answer || [])
  .map(function (r) { return String(r.data || '').replace(/"/g, ''); })
  .filter(function (t) { return /^v=spf1/i.test(t); });

// RDAP is keyless and answers in about a second. `registration` is the field
// that matters: a domain registered a week before the signup is the strongest
// free fraud signal available, and nothing else here can see it. A TLD with no
// RDAP server, or a rate-limited answer, means no signal - never a rejection.
const rdapRaw = $('Ask Who Registered The Domain').first().json || {};
let rdap = rdapRaw;
if (typeof rdapRaw.data === 'string') {
  try { rdap = JSON.parse(rdapRaw.data); } catch (e) { rdap = {}; }
} else if (rdapRaw.body && typeof rdapRaw.body === 'object') {
  rdap = rdapRaw.body;
}
let registered = '';
let expires = '';
for (const ev of (rdap.events || [])) {
  if (ev.eventAction === 'registration') { registered = String(ev.eventDate || '').slice(0, 10); }
  if (ev.eventAction === 'expiration') { expires = String(ev.eventDate || '').slice(0, 10); }
}
const ageDays = registered
  ? Math.round((Date.now() - new Date(registered + 'T00:00:00Z').getTime()) / 86400000)
  : null;
const daysToExpiry = expires
  ? Math.round((new Date(expires + 'T00:00:00Z').getTime() - Date.now()) / 86400000)
  : null;

// Which mail provider, read off the MX hosts. Useful on its own: knowing an
// address is on Google Workspace or Microsoft 365 says the domain is somebody's
// actual company.
let provider = '';
const joined = hosts.join(' ');
if (/google\.com|googlemail\.com/.test(joined)) { provider = 'Google'; }
else if (/outlook\.com|protection\.outlook|microsoft/.test(joined)) { provider = 'Microsoft'; }
else if (/zoho/.test(joined)) { provider = 'Zoho'; }
else if (/pphosted|proofpoint/.test(joined)) { provider = 'Proofpoint'; }
else if (/mimecast/.test(joined)) { provider = 'Mimecast'; }
else if (hosts.length) { provider = hosts[0].split('.').slice(-2).join('.'); }

// The blocklist arrives as one domain per line, 8,695 of them.
const listRaw = $('Fetch The Disposable List').first().json || {};
const listText = typeof listRaw === 'string' ? listRaw : String(listRaw.data || listRaw.body || '');
const disposable = new Set(
  listText.split('\n').map(function (l) { return l.trim().toLowerCase(); }).filter(Boolean)
);

return [{ json: Object.assign({}, asked, {
  nxdomain: nxdomain,
  mx_hosts: hosts,
  mx_count: mxAnswers.length,
  null_mx: nullMx,
  has_a: aAnswers.length > 0,
  dmarc: dmarcTxt.length ? dmarcTxt[0] : '',
  provider: provider,
  has_spf: spfTxt.length > 0,
  registered_on: registered,
  domain_age_days: ageDays,
  days_to_expiry: daysToExpiry,
  is_disposable: disposable.has(asked.domain),
  blocklist_size: disposable.size,
})}];

// Did they mean something else?
//
// Only against the domains people actually mistype, and only at a distance of
// one or two - "gmial.com" is worth a suggestion, "gmail.co.uk" is a real
// domain and must never be corrected.
const cfg = $('Settings').first().json;
// single-item input: one request, one address.
const j = $input.first().json;

const candidates = String(cfg.common_domains || '')
  .split(',').map(function (d) { return d.trim().toLowerCase(); }).filter(Boolean);

function distance(a, b) {
  if (a === b) { return 0; }
  const m = a.length, n = b.length;
  if (Math.abs(m - n) > 2) { return 9; }
  let prev = [];
  for (let i = 0; i <= n; i++) { prev.push(i); }
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let k = 1; k <= n; k++) {
      cur[k] = Math.min(
        prev[k] + 1,
        cur[k - 1] + 1,
        prev[k - 1] + (a.charAt(i - 1) === b.charAt(k - 1) ? 0 : 1)
      );
    }
    prev = cur;
  }
  return prev[n];
}

let suggestion = '';
if (j.domain && candidates.indexOf(j.domain) < 0) {
  let best = null;
  for (const c of candidates) {
    const d = distance(j.domain, c);
    if (d >= 1 && d <= 2 && (!best || d < best.d)) { best = { c: c, d: d }; }
  }
  if (best) { suggestion = j.local + '@' + best.c; }
}

return [{ json: Object.assign({}, j, { suggestion: suggestion }) }];

// One verdict, and the reasons that produced it.
//
// Three outcomes rather than two, because "this is not a person" and "this is
// not an address" are different problems and only one of them is the typist's
// fault.
//
// single-item input: one request, one address.
//
// The address is read by name. `Read What You Have Seen` sits between the typo
// check and here, and a Data Table read replaces the item with its rows - on
// an empty table that is one empty object, and every field below is undefined.
const cfg = $('Settings').first().json;
const j = $('Did They Mean Something Else?').first().json;

const roles = String(cfg.role_prefixes || '')
  .split(',').map(function (r) { return r.trim().toLowerCase(); }).filter(Boolean);
const free = String(cfg.free_providers || '')
  .split(',').map(function (r) { return r.trim().toLowerCase(); }).filter(Boolean);

const seenBefore = $('Read What You Have Seen').all()
  .map(function (i) { return i.json || {}; })
  .filter(function (r) { return String(r.address_key || '') === j.address_key; });

const isRole = roles.indexOf(j.local.split('+')[0]) >= 0;
const isFree = free.indexOf(j.domain) >= 0;

const reasons = [];
let verdict = 'accept';

// The suggestion goes first whatever else happens. `gmial.com` is on the
// disposable blocklist, so the honest verdict is reject - but "did they mean
// gmail.com" is the sentence the person filling in the form needs, and it was
// buried under the blocklist reason on the first live run.
if (j.suggestion) { reasons.push('Did they mean ' + j.suggestion + '?'); }

function reject(why) { verdict = 'reject'; reasons.push(why); }
function review(why) { if (verdict !== 'reject') { verdict = 'review'; } reasons.push(why); }

if (!j.looks_like_an_address) {
  reject(j.email ? 'That is not the shape of an email address.' : 'No address was sent.');
} else if (j.nxdomain) {
  reject('The domain ' + j.domain + ' does not exist.');
} else if (j.null_mx) {
  reject('The domain publishes a null MX record, which is how a domain says it accepts no mail at all.');
} else if (j.is_disposable) {
  reject('The domain is on the public disposable-address blocklist.');
} else if (!j.mx_count && !j.has_a) {
  reject('The domain has no mail server and no address record. Nothing would arrive.');
}

if (verdict !== 'reject') {
  if (!j.mx_count && j.has_a) {
    review('No MX record. Mail would fall back to the A record, which works but is almost always somebody forgetting to set MX.');
  }
  if (j.suggestion && verdict === 'accept') {
    verdict = 'review';
  }
  if (isRole) {
    if (String(cfg.role_addresses || 'review') === 'reject') {
      reject('Role address, not a person.');
    } else {
      review('Role address rather than a person. It will reach somebody, but not anybody in particular.');
    }
  }
  if (seenBefore.length >= Number(cfg.repeat_threshold || 5)) {
    review('This address has been checked ' + seenBefore.length + ' times already.');
  }
  // Null means the TLD has no RDAP service - .io answers 404 to every query -
  // rather than "this domain is new". No signal is not a bad signal.
  if (j.domain_age_days !== null && j.domain_age_days < Number(cfg.min_domain_age_days || 30)) {
    review('The domain was registered ' + j.domain_age_days + ' days ago. New domains behind signups are usually throwaway.');
  }
  if (j.days_to_expiry !== null && j.days_to_expiry < 30) {
    review('The domain expires in ' + j.days_to_expiry + ' days.');
  }
  if (!isFree && !j.has_spf && !j.dmarc && j.mx_count) {
    review('The domain publishes neither SPF nor DMARC, which is unusual for a company that sends mail.');
  }
}

if (verdict === 'accept' && !reasons.length) {
  reasons.push(j.provider ? 'Deliverable, mail handled by ' + j.provider + '.' : 'Deliverable.');
}

return [{ json: {
  email: j.email,
  address_key: j.address_key,
  domain: j.domain,
  verdict: verdict,
  reasons: reasons,
  suggestion: j.suggestion || '',
  role_address: isRole,
  free_provider: isFree,
  disposable: !!j.is_disposable,
  mail_provider: j.provider || '',
  has_dmarc: !!j.dmarc,
  has_spf: !!j.has_spf,
  domain_age_days: j.domain_age_days,
  checked_on: new Date().toISOString().slice(0, 10),
}}];
